solution:
from dataclasses import dataclass

@dataclass
class Concentrato:
    F: float

@dataclass
class Distribuito:
    q: float
    L: float

def risultante(c):
    match c:
        case Concentrato(F=F):
            return F
        case Distribuito(q=q, L=L):
            return q * L

print(sum(risultante(c) for c in [Concentrato(10), Distribuito(2, 3)]))
